/**
 * @param browserList 浏览器版本列表
 * @param support 支持 or 不支持
 */
;(function (global, factory) {
  typeof exports === 'object' && typeof module !== 'undefined'
    ? (module.exports = factory())
    : typeof define === 'function' && define.amd
    ? define(factory)
    : typeof global !== 'undefined'
    ? (global.SupportBrowser = factory())
    : (self.SupportBrowser = factory())
})(this, function () {
  const imgBase64 =
    'data:image/png;base64,'
  // 例如:
  // supportBrowser(['<ie11', 'safari'], false) 不支持<ie11、safari
  // supportBrowser(['chrome']) 仅支持chrome
  function supportBrowser(browserList, support) {
    if (support === undefined) {
      support = true
    }
    let isSupport = !support
    const myBrowser = getBrowser()
    const myBrowserName = myBrowser.split('/')[0]
    const myBrowserVersion = myBrowser.split('/')[1] ? myBrowser.split('/')[1].split('.')[0] : ''

    for (let i = 0; i < browserList.length; i++) {
      const browser = browserList[i].toLowerCase()
      const reg = /([\<|\>]=?)?(ie|safari|chrome|edge|firefox|opera)\/?([\.?\d*]*)/
      if (reg.test(browser)) {
        const regExp = reg.exec(browser)
        const dir = regExp[1] // > < =
        const browserName = regExp[2]
        const browserVersion = regExp[3] ? regExp[3].replace(/\./g, '') : ''
        if (myBrowserName === browserName) {
          if (dir && browserVersion) {
            // 比较版本
            // eslint-disable-next-line
            var compare = eval(myBrowserVersion + dir + browserVersion)
            // 判断条件为'支持'，使用版本比较结果，否则取反
            isSupport = support ? compare : !compare
          } else {
            isSupport = support
          }
          break
        }
      }
    }
    if (!isSupport) {
      document.body.innerHTML =
        // '<div style="height: 100%; width: 100%;position: relative;">' +
        // '<div style="height: 475px; width: 720px;position: absolute;left:50%;top:50%;margin-left:-360px;margin-top:-238px;text-align: center;font-size: 26px;color: #333;">' +
        // '<img src="' + imgBase64 + '">' +
        // '<p style="margin-bottom: 18px;">呃...浏览器有兼容性问题</p>' +
        // '<p>请尝试使用其他浏览器（推荐使用最新版本的chrome浏览器）</p>' +
        // '</div>' +
        // '</div>'
        '<div style="height: 100%; width: 100%;position: relative;">' +
        '<div style="height: 40%; width: 80%;position: absolute;left:50%;top:50%;margin-left:-40%;margin-top:-15%;text-align: center;font-size: 26px;color: #333;">' +
        '<img src="' +
        imgBase64 +
        '">' +
        '<p style="margin-bottom: 18px;">呃...浏览器有兼容性问题</p>' +
        '<p>请尝试使用其他浏览器（推荐使用最新版本的chrome浏览器）</p>' +
        '</div>' +
        '</div>'
    }
  }

  function getBrowser() {
    const userAgent = navigator.userAgent
    let browser = ''
    if (/MSIE ([\d.]+)/.test(userAgent)) {
      // IE5/6/7/8/9/10
      const ieVersion = parseFloat(/MSIE ([\d.]+)/.exec(userAgent)[1])
      browser = 'ie/' + ieVersion
    } else if (!!window.ActiveXObject || 'ActiveXObject' in window) {
      // IE11
      browser = 'ie/11'
    } else if (userAgent.indexOf('Edg') > -1) {
      // IEdge（先）
      browser = userAgent.match(/Edg\/([\d.]+)/)[0].toLowerCase()
    } else if (userAgent.indexOf('Chrome') > -1 && userAgent.indexOf('Safari') > -1) {
      // Chrome（后）
      browser = userAgent.match(/Chrome\/([\d.]+)/)[0].toLowerCase()
    } else if (userAgent.indexOf('Safari') && /Version\/([\d.]+)/.test(userAgent)) {
      // Safari
      browser = 'safari/' + /Version\/([\d.]+)/.exec(userAgent)[1]
    } else if (userAgent.indexOf('Opera') && /Version\/([\d.]+)/.test(userAgent)) {
      // Opera
      browser = 'opera/' + /Version\/([\d.]+)/.exec(userAgent)[1]
    } else if (userAgent.indexOf('Firefox') > -1) {
      // Firefox
      browser = userAgent.match(/Firefox\/([\d.]+)/)[0].toLowerCase()
    } else {
      browser = 'other'
    }
    return browser
  }
  return supportBrowser
})
